#!/bin/sh

# Exit on error
set -e

if [ -z "$RELEASE" ]; then
    echo "\$RELEASE not set, aborting"
    exit 1
fi

pkgver=$(echo "$RELEASE" | sed 's/v//')

cat << EOF > ./PKGBUILD
# Maintainer: TODO_SET_MAINTAINER_NAME_AND_EMAIL
# omarchy-chrome is a Firefox chrome theme for Omarchy, forked from
# firefox-gnome-theme (https://github.com/rafaelmardojai/firefox-gnome-theme).
# This PKGBUILD is automatically generated by
# TODO_SET_REPO_URL/blob/$RELEASE/scripts/generate-pkgbuild.sh
# when a release is published on GitHub. Do not edit this file directly.

pkgname=omarchy-chrome
pkgver=$pkgver
pkgrel=1
pkgdesc='A Firefox chrome theme for Omarchy'
arch=('any')
url="TODO_SET_REPO_URL"
license=('Unlicense')
optdepends=('firefox: primary compatible browser' 'librewolf: alternative compatible browser')
conflicts=("\$pkgname-git")
source=("\$pkgname-\$pkgver.tar.gz::TODO_SET_REPO_URL/archive/refs/tags/v\$pkgver.tar.gz")
md5sums=('TO_BE_GENERATED')

package() {
	cd "\$srcdir/\$pkgname-\$pkgver"
	install -d "\$pkgdir/usr/share/\$pkgname"
	cp -ra theme userChrome.css userContent.css configuration "\$pkgdir/usr/share/\$pkgname"

	# Install docs
	install -Dm644 README.md "\$pkgdir/usr/share/doc/\$pkgname/README.md"
}
EOF
